            domain=pyo.NonNegativeReals
        )  # Electricity to regulated market
        m.q_el_free = pyo.Var(domain=pyo.NonNegativeReals)  # Electricity to free market
        m.q_mol = pyo.Var(domain=pyo.NonNegativeReals)  # Molasses produced

        # CONSTRAINTS
        # Superstructure

        def CoP(m):
            return m.costs == (
                (m.q_sugar_free + m.q_sugar_reg) * prodcost["sug"]
                + (m.q_eth_free + m.q_eth_reg) * prodcost["eth"]
                + (m.q_el_free + m.q_el_reg) * prodcost["fre"]
            )

        m.c = pyo.Constraint(rule=CoP)

        def mass_balance(m):
            return m.x_bag + m.x_jui == 1

        m.mass_balance = pyo.Constraint(rule=mass_balance)

        def juice_production(m):
            return (
                m.r["jui", "mill"]
                == conv["cane", "mill", "jui"] * Ca * m.x_jui * m.SugarYieldSample
            )

        m.juice_production = pyo.Constraint(rule=juice_production)

        def bagasse_production(m):
            return (
                m.r["bag", "mill"]
                == conv["cane", "mill", "bag"] * Ca * m.x_bag * m.SugarYieldSample
            )

        m.bagasse_production = pyo.Constraint(rule=bagasse_production)

        def juice1(m):
            return m.x_jui == m.x_juiF + m.x_juiD

        m.juiceeq1 = pyo.Constraint(rule=juice1)

        def juice_flow_fact(m):
            return m.r["jui", "fact"] == m.x_juiF * m.r["jui", "mill"]

        m.juice_flow_fact = pyo.Constraint(rule=juice_flow_fact)

        def capacity_fact(m):
            return m.x_juiF * m.x_jui * Ca <= max_cap["fact"]

        m.capacity_fact = pyo.Constraint(rule=capacity_fact)

        def juice_flow_dist(m):
            return m.r["jui", "dist"] == m.x_juiD * m.r["jui", "mill"]

        m.juice_flow_dist = pyo.Constraint(rule=juice_flow_dist)

        def juice25(m):
            return m.r["jui", "fact"] <= max_cap["fact"]

        m.juiceeq25 = pyo.Constraint(rule=juice25)

        def capacity_dist(m):
            return m.x_juiD * m.x_jui * Ca <= max_cap["dist"]

        m.capacity_dist = pyo.Constraint(rule=capacity_dist)

        def juice35(m):
            return m.r["jui", "dist"] <= max_cap["dist"]

        m.juiceeq35 = pyo.Constraint(rule=juice35)

        def sugar_production(m):
            return (
                m.q_sugar_reg + m.q_sugar_free
                == conv["jui", "fact", "sug"] * m.r["jui", "fact"]
            )

        m.sugar_production = pyo.Constraint(rule=sugar_production)

        def sugar2(m):
            return m.q_mol == gen["fact", "mol"] * (m.q_sugar_reg + m.q_sugar_free)

        m.su2 = pyo.Constraint(rule=sugar2)

        def sugar3(m):
            return m.q_sugar_reg <= 90000

        m.su3 = pyo.Constraint(rule=sugar3)

        def ethanol_production(m):
            return m.q_eth_reg + m.q_eth_free == (
                conv["jui", "dist", "eth"] * m.r["jui", "dist"]
                + conv["mol", "dist", "eth"] * m.q_mol
            )

        m.ethanol_production = pyo.Constraint(rule=ethanol_production)

        def ethanol2(m):
            return m.q_eth_reg <= 77000

        m.et2 = pyo.Constraint(rule=ethanol2)

        def el_prod(m):
            return (
                m.q_el_reg + m.q_el_free == Ca * m.SugarYieldSample * 0.053
            )  # 53 kWh produced per ton of sugarcane processes

        m.el_produced = pyo.Constraint(rule=el_prod)

        def min_sugar_reg_sales(m):
            return m.q_sugar_reg >= 20000

        m.min_sugar_reg_sales = pyo.Constraint(rule=min_sugar_reg_sales)

        def min_eth_reg_sales(m):
            return m.q_eth_reg >= 20000

        m.min_eth_reg_sales = pyo.Constraint(rule=min_eth_reg_sales)

        def min_sugar_free_sales(m):
            return m.q_sugar_free >= 1000

        m.min_sugar_free_sales = pyo.Constraint(rule=min_sugar_free_sales)

        def min_eth_free_sales(m):
            return m.q_eth_free >= 1000

        m.min_eth_free_sales = pyo.Constraint(rule=min_eth_free_sales)

        M = 1e6

        m.exceeds_sugar_limit = pyo.Var(domain=pyo.Binary)
        m.exceeds_eth_limit = pyo.Var(domain=pyo.Binary)

        def sugar_limit_rule(m):
            return m.q_sugar_reg <= reg_sugar_limit + M * m.exceeds_sugar_limit

        m.sugar_limit_constraint = pyo.Constraint(rule=sugar_limit_rule)

        def sugar_over_limit_rule(m):
            return m.q_sugar_reg >= reg_sugar_limit * (1 - m.exceeds_sugar_limit)

        m.sugar_over_limit_constraint = pyo.Constraint(rule=sugar_over_limit_rule)

        # Add constraints to enforce binary variable logic for ethanol
        def eth_limit_rule(m):
            return m.q_eth_reg <= reg_eth_limit + M * m.exceeds_eth_limit

        m.eth_limit_constraint = pyo.Constraint(rule=eth_limit_rule)

        def eth_over_limit_rule(m):
            return m.q_eth_reg >= reg_eth_limit * (1 - m.exceeds_eth_limit)

        m.eth_over_limit_constraint = pyo.Constraint(rule=eth_over_limit_rule)

        # Expected Profit
        def profit(m, q):
            sugar_reg_price = m.price_reg_sug[q] * (1 - 0.5 * m.exceeds_sugar_limit)
            ethanol_reg_price = m.price_reg_eth[q] * (1 - 0.5 * m.exceeds_eth_limit)
            revenue = (
                m.q_sugar_free * hp[q, "sug"]
                + m.q_sugar_reg * sugar_reg_price
                + m.q_eth_free * hp[q, "eth"]
                + m.q_eth_reg * ethanol_reg_price
                + m.q_el_free * hp[q, "fre"]
                + m.q_el_reg * price_reg_el
            )
            cost = m.costs
            return m.profit[q] == revenue - cost

        m.profiteq = pyo.Constraint(m.price_time_obs, rule=profit)

        def eprofit1(m):
            total_profit = sum(m.profit[q] for q in m.price_time_obs)
            return m.EP == total_profit / (m.N)

        m.ep2 = pyo.Constraint(rule=eprofit1)

        # Product Revenues to be used in analysis
        def sug_Fprof(m):
            return sum(m.q_sugar_free * hp[q, "sug"] for q in m.price_time_obs) * (
                1 / N
            )

        m.avg_sug_Fprof = pyo.Expression(rule=sug_Fprof)

        def eth_Fprof(m):
            return sum(m.q_eth_free * hp[q, "eth"] for q in m.price_time_obs) * (1 / N)

        m.avg_eth_Fprof = pyo.Expression(rule=eth_Fprof)

        def sug_Rprof(m):
            return sum(
                m.q_sugar_reg * (m.price_reg_sug[q] * (1 - 0.5 * m.exceeds_sugar_limit))
                for q in m.price_time_obs
            ) * (1 / N)

        m.avg_sug_Rprof = pyo.Expression(rule=sug_Rprof)

        def eth_Rprof(m):
            return sum(
                m.q_eth_reg * (m.price_reg_eth[q] * (1 - 0.5 * m.exceeds_eth_limit))
                for q in m.price_time_obs
            ) * (1 / N)

        m.avg_eth_Rprof = pyo.Expression(rule=eth_Rprof)

        def el_prof(m):
            return sum(m.q_el_free * hp[q, "fre"] for q in m.price_time_obs) * (1 / N)

        m.avg_el_prof = pyo.Expression(rule=el_prof)
    else:
        # PYOMO SETS

        bin_width = [1541400 / bin_count for i in range(bin_count)]
        bins = [0 for i in range(bin_count)]
        bin_indices = [i for i in range(bin_count)]

        m.resources = pyo.Set(initialize=resources)
        m.saleable_products = pyo.Set(initialize=saleable_products)
        m.processes = pyo.Set(initialize=processes)
        m.price_time_obs = pyo.Set(initialize=q)
        m.commodities = pyo.Set(initialize=commodity)

        m.N = pyo.Param(initialize=N)

        # VARIABLES
        # Positive Variables
        m.x = pyo.Var(m.resources, domain=pyo.NonNegativeReals)
        m.r = pyo.Var(
            m.resources, m.processes, domain=pyo.NonNegativeReals
        )  # For juice split point
        m.profit = pyo.Var(m.price_time_obs)
        m.EP = pyo.Var()
        m.S_bins = pyo.Var(bin_indices, domain=pyo.NonNegativeReals)

        # Adding randomness in yield ranging from -20% to +20%
        yield_factors = np.random.uniform(0.8, 1.2, 6)
        jui_yield, bag_yield, sug_yield, mol_yield, el_yield, eth_yield = yield_factors

        # CONSTRAINTS
        # Superstructure Constraints
        def mill1(m):
            return m.x["jui"] * jui_yield == Ca * conv["cane", "mill", "jui"]

        m.milleq1 = pyo.Constraint(rule=mill1)

        def mill2(m):
            return m.x["bag"] * bag_yield == Ca * conv["cane", "mill", "bag"]

        m.milleq2 = pyo.Constraint(rule=mill2)

        def juice1(m):
            return m.x["jui"] * jui_yield == m.r["jui", "fact"] + m.r["jui", "dist"]

        m.juiceeq1 = pyo.Constraint(rule=juice1)

        def juice2(m):
            return m.r["jui", "fact"] <= max_cap["fact"]

        m.juiceeq2 = pyo.Constraint(rule=juice2)

        def juice3(m):
            return m.r["jui", "dist"] <= max_cap["dist"]

        m.juiceeq3 = pyo.Constraint(rule=juice3)

        def sugar1(m):
            return (
                m.x["sug"] * sug_yield
                == conv["jui", "fact", "sug"] * m.r["jui", "fact"]
            )

        m.su1 = pyo.Constraint(rule=sugar1)

        def sugar2(m):
            return m.x["mol"] * mol_yield == gen["fact", "mol"] * m.x["sug"]

        m.su2 = pyo.Constraint(rule=sugar2)

        def ethanol1(m):
            return (
                m.x["eth"] * eth_yield
                == conv["jui", "dist", "eth"] * m.r["jui", "dist"]
                + conv["mol", "dist", "eth"] * m.x["mol"]
            )

        m.et1 = pyo.Constraint(rule=ethanol1)

        def el_prod(m):
            return (
                m.x["el-r"] * el_yield == Ca * 0.053
            )  # 53 kWh produced per ton of sugarcane processes

        m.el_produced = pyo.Constraint(rule=el_prod)

        def el_sales(m):
            return m.x["fre"] + m.x["reg"] == m.x["el-r"] * el_yield

        m.electricity = pyo.Constraint(rule=el_sales)

        # sugar cane reformulation
        def sugar_sum(m):
            return m.x["sug"] == sum(m.S_bins[i] for i in range(bin_count))

        m.sugar_tot_sum = pyo.Constraint(rule=sugar_sum)

        for i in range(bin_count):
            m.add_component(
                f"bin_{i+1}_max", pyo.Constraint(expr=m.S_bins[i] <= bin_width[i])
            )

        # Cap on regulated electricity
        def el_reg_cap(m):
            return m.x["reg"] <= 100000

        m.reg_cap = pyo.Constraint(rule=el_reg_cap)

        # Expected Profit
        def profit(m, q):
            return m.profit[q] == sum(
                m.S_bins[z]
                * (
                    hp[q, "sug"]
                    - (hp[q, "sug"] - scale_hyp * 321.92) * (bin_count - z) / bin_count
                )
                for z in range(bin_count)
            ) + eth_yield * m.x["eth"] * hp[q, "eth"] + m.x["fre"] * hp[q, "fre"] + m.x[
                "reg"
            ] * price_reg - sum(
                m.x[j] * prodcost[j] for j in m.saleable_products
            )

        m.profiteq = pyo.Constraint(m.price_time_obs, rule=profit)

        def eprofit1(m):
            return m.EP == (1 / N) * sum(m.profit[q] for q in m.price_time_obs)

        m.ep1 = pyo.Constraint(rule=eprofit1)

        # Product Revenues to be used in analysis
        def sug_prof(m):
            return sum(
                sum(
                    m.S_bins[z]
                    * (
                        hp[q, "sug"]
                        - (hp[q, "sug"] - 2 / 3 * 321.92) * (bin_count - z) / bin_count
                    )
                    for z in range(bin_count)
                )
                for q in m.price_time_obs
            ) * (1 / N)

        m.avg_sug_prof = pyo.Expression(rule=sug_prof)

        def eth_prof(m):
            return sum(m.x["eth"] * hp[q, "eth"] for q in m.price_time_obs) * (1 / N)

        m.avg_eth_prof = pyo.Expression(rule=eth_prof)

        def el_prof(m):
            return sum(m.x["fre"] * hp[q, "fre"] for q in m.price_time_obs) * (1 / N)

        m.avg_el_prof = pyo.Expression(rule=el_prof)

    return m

MV (Mean value)\begin{align*}
MV = \sum_{i=1}^{n} \sum_{j=1}^{n} \sigma_{i,j} x_i x_j
\end{align*}

MAD (Mean Absolute Deviation)\begin{align*}
MAD = E \left[ \mid \sum_{j=1}^{n} R_j x_j -E \left[ \sum_{j=1}^{n} R_j x_j \right] \mid \right]
\end{align*}

CVaR (Conditional Value-at-Risk)\begin{align*}
VaR_{\beta} = \max V \\
s.t.  \sum_{j=1}^{N} 1 \left[ V - R_j \right] \leq (1-\beta)N
\end{align*}\begin{align*}
CVaR_{\beta} = VaR_{\beta} - \frac{1}{(1-\beta)N}  \sum_{j=1}^{N} max \left[ 0, VaR_{\beta} - R_j \right]
\end{align*}

Chemical reactors are often the most important unit operations in a chemical plant. Reactors come in many forms, however two of the most common idealizations are the continuously stirred tank reactor (CSTR) and the plug flow reactor. The CSTR is often used in modeling studies, and it can be effectively modeled as a lumped parameter system. In this example, we will consider the following reaction scheme known as the Van de Vusse reaction:\text{A} \xrightarrow{k_1} \text{B} \xrightarrow{k_2} \text{C}2\text{A} \xrightarrow{k_3} \text{D}

A diagram of the system is shown in figure below, where F is the volumetric flowrate. The reactor is assumed to be filled to a constant volume, and the mixture is assumed to have constant density, so the volumetric flowrate into the reactor is equal to the volumetric flowrate out of the reactor. Since the reactor is assumed to be well mixed, the concentrations in the reactor are equivalent to the concentrations of each component flowing out of the reactor, given by C_A, C_B, C_C, and C_D.

This example (both text and figure) was taken from Bynum et al. (2021), §7.4.4, p. 106.

The goal is to produce product B from a feed containing reactant A. If we design a reactor that is too small, we will obtain insufficient conversion of A to the desired product B. However, given the reaction scheme, if the reactor is too large (e.g., too much reaction is allowed to occur), a significant amount of the desired product B will be further reacted to form the undesired product C. As a result, the goal in this exercise will be to solve for the optimal reactor volume producing the maximum outlet concentration for product B.

The steady-state mole balances for each of the four components are given by,\begin{align*}
&0=\frac{F}{V}C_{Af}-\frac{F}{V}C_A-k_1C_A-2k_3C_A^2 \\
& 0=-\frac{F}{V}C_B+k_1C_A-k_2C_B\\
& 0=-\frac{F}{V}C_C+k_2C_B \\
& 0=-\frac{F}{V}C_D+k_3C_A^2
\end{align*}

The known parameters for the system are,\begin{align*}
C_{Af}=10^4\,\mathrm{\frac{gmol}{m^3}}\quad{k_1=\frac{5}{6}\,\mathrm{min^{-1}}}\quad{k_2=\frac{5}{3}\,\mathrm{min^{-1}}}\quad{k_3=\frac{1}{6000}\,\mathrm{\frac{m^3}{gmol\cdot min}}}
\end{align*}

Since the volumetric flowrate F always appears as the numerator over the reactor volume V, it is common to consider this ratio as a single variable, called the space velocity (sv). Our optimization formulation will seek to find the space-velocity that maximizes the outlet concentration of the desired product B.

This original problem was taken from Bynum et al. (2021), §7.4.4, p. 106.

In this project, species C is the desired product, and we are considering the dynamic state of the system (most often, industrial operations are dynamic). The goal of this work is to determine the volume of the reactor that will maximize the concentration of species C in the effluent after 10 minutes. Furthermore, for economic reasons, the reactor volume should not exceed \mathrm{100\,m^3}.

The mole balance for each of the species in this system under dynamic state is given by:\begin{align*}
&\frac{dC_A}{dt}=\frac{F}{V}C_{Af}-\frac{F}{V}C_A-k_1C_A-2k_3C_A^2 \\
& \frac{dC_B}{dt}=-\frac{F}{V}C_B+k_1C_A-k_2C_B\\
& \frac{dC_C}{dt}=-\frac{F}{V}C_C+k_2C_B \\
& \frac{dC_D}{dt}=-\frac{F}{V}C_D+k_3C_A^2
\end{align*}

Where C_A, C_B, C_C and C_D are the concentrations of species A, B, C and D, respectively. F is the feed flow rate, C_{Af} is the concentration of species A in the feed, k_1, k_2 and k_3 are the rate constants of reaction 1 (species A to B), reaction 2 (species B to C) and reaction 3 (species A to D), respectively.

The data for the system are:\begin{align*}
C_{Af}=10^4\,\mathrm{\frac{mol}{m^3}},\quad{k_1=\frac{5}{6}\,\mathrm{min^{-1}}},\quad{k_2=\frac{5}{3}\,\mathrm{min^{-1}}},\quad{k_3=\frac{1}{6000}\,\mathrm{\frac{m^3}{mol\cdot min}}},\quad{F=1\,\mathrm{\frac{m^3}{min}}}
\end{align*}

The data was obtained from Bynum et al. (2021), §7.4.4, p. 106.

We formulated a model without water involved (as it is in the dataframe). There are four types of food: broccoli, bread, steak, and Popeyes (four piece combo). We chose these items because they are the most common, meanwhile each has its unique attributes: broccoli is only high in fiber, bread is only high in carbs, steak is high in protein and fat, and Popeyes is high in protein, fat, and decent in carbs. Among these options, Popeyes is the most well-rounded food item, providing most nutrients in abundance.
Before we solve the model, we believe that the best combination would be Popeyes with some bread as well as broccoli that is enough to satisfy the fiber needs, whereas steak would be ignored because of Popeyes’ nutritional value (though sounds odd).

model = pyo.ConcreteModel()

# Define the food items
food_items = ["broccoli", "bread", "steak", "Popeyes"]

# Define the nutrition and price data
nutrition_data = {
    "Protein": [2.6, 3.5, 26, 76],
    "Carbohydrates": [6, 19.5, 0, 36],
    "Fat": [0.3, 0.84, 7.6, 64],
    "Fiber": [2, 1.16, 0, 0],
    "Volume": [2.6, 1.41, 3, 25],
    "Price": [2, 1.5, 6, 25],
}

# Define the bounds for each constraint
bounds = {"Protein": 70, "Carbohydrates": 250, "Fat": 70, "Fiber": 35, "Volume": 90}

# Define the decision variables for the amount of each food item
model.food_quantities = pyo.Var(food_items, domain=pyo.NonNegativeReals)

# Define the objective function to minimize the total price
model.obj = pyo.Objective(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Price"][j]
        for j, i in enumerate(food_items)
    ),
    sense=pyo.minimize,
)

# Add constraints for total intake of protein, carbohydrates, fat, fiber, and volume
model.protein_constraint = pyo.Constraint(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Protein"][j]
        for j, i in enumerate(food_items)
    )
    >= bounds["Protein"]
)
model.carbohydrates_constraint = pyo.Constraint(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Carbohydrates"][j]
        for j, i in enumerate(food_items)
    )
    >= bounds["Carbohydrates"]
)
model.fat_constraint = pyo.Constraint(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Fat"][j]
        for j, i in enumerate(food_items)
    )
    >= bounds["Fat"]
)
model.fiber_constraint = pyo.Constraint(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Fiber"][j]
        for j, i in enumerate(food_items)
    )
    >= bounds["Fiber"]
)
model.volume_constraint = pyo.Constraint(
    expr=sum(
        model.food_quantities[i] * nutrition_data["Volume"][j]
        for j, i in enumerate(food_items)
    )
    <= bounds["Volume"]
)

# Solve the problem using IPOPT solver
solver = pyo.SolverFactory("ipopt")
results = solver.solve(model, tee=True)

# Print the results
print("Status:", results.solver.termination_condition)
print("Optimal solution:")
for i in food_items:
    print(f"{i}: {pyo.value(model.food_quantities[i]):.2f} units")

# Print the total price
total_price = sum(
    pyo.value(model.food_quantities[i]) * nutrition_data["Price"][j]
    for j, i in enumerate(food_items)
)
print(f"Total price: ${total_price:.2f}")





From the model output, we can see that the results are pretty similar to what we imagined at first: 0.94 units of Popeyes, 6.94 units of bread, 13.47 units of broccoli, and no steak. These units translated into normal weights dimensions are: almost one serving of the Popeyes four-piece chicken combo, 2 pounds of broccoli, and 0.6 pound of bread. Steak is not selected at all primarily because it is not an economically efficient option for its nutritional values, as the two of its competitive edges (protein and fat) are both covered by Popeyes.

Now we want to formulate a model with water involved. Water has no nutritional value but volume. We also added a constraint specifying the amount of water to be consumed per day: 3 bottles of 10 oz size, in order to imitate real-life situations more accurately.

