        "Fiber": [2, 1.16, 0, 0, 0],
        "Volume": [2.6, 1.41, 3, 25, 10],
        "Price": [2, 1.5, 6, 25, 2.5],
    }

    bounds = {"Protein": 70, "Carbohydrates": 250, "Fat": 70, "Fiber": 35, "Volume": 90}

    model.food_quantities = pyo.Var(food_items, domain=pyo.NonNegativeReals)

    model.obj = pyo.Objective(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Price"][j]
            for j, i in enumerate(food_items)
        ),
        sense=pyo.minimize,
    )

    model.protein_constraint = pyo.Constraint(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Protein"][j]
            for j, i in enumerate(food_items)
        )
        >= bounds["Protein"]
    )
    model.carbohydrates_constraint = pyo.Constraint(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Carbohydrates"][j]
            for j, i in enumerate(food_items)
        )
        >= bounds["Carbohydrates"]
    )
    model.fat_constraint = pyo.Constraint(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Fat"][j]
            for j, i in enumerate(food_items)
        )
        >= bounds["Fat"]
    )
    model.fiber_constraint = pyo.Constraint(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Fiber"][j]
            for j, i in enumerate(food_items)
        )
        >= bounds["Fiber"]
    )
    model.volume_constraint = pyo.Constraint(
        expr=sum(
            model.food_quantities[i] * nutrition_data["Volume"][j]
            for j, i in enumerate(food_items)
        )
        <= bounds["Volume"]
    )
    model.water_constraint = pyo.Constraint(expr=model.food_quantities["water"] == 3)

    solver = pyo.SolverFactory("ipopt")
    results = solver.solve(model)
    assert pyo.check_optimal_termination(results), (
        f"Solve failed: status={results.solver.status}, "
        f"termination={results.solver.termination_condition}"
    )

    # Return the selected quantity of steak
    return pyo.value(model.food_quantities["steak"])


